package motion
import ("math";"testing")
func rigs()(Rig,Rig){return Rig{.48,.46},Rig{.53,.47}}
func TestGeometry(t *testing.T){a,b:=rigs();for _,r:=range []Rig{a,b}{for i:=0;i<100;i++{p:=Pose{-.3+float64(i)*.006,.5+float64(i)*.006};v,e:=FK(r,p);if e!=nil{t.Fatal(e)};q,e:=IK(r,v);if e!=nil{t.Fatal(e)};if math.Abs(q.Hip-p.Hip)>1e-9||math.Abs(q.Knee-p.Knee)>1e-9{t.Fatalf("FK/IK mismatch: %v to %v",p,q)}}}}
func TestInvalidInputs(t *testing.T){a,_:=rigs();if _,e:=IK(a,Vec{3,0});e==nil{t.Fatal("unreachable accepted")};if _,e:=FK(Rig{-1,1},Pose{});e==nil{t.Fatal("invalid rig accepted")};if _,e:=FK(a,Pose{math.NaN(),0});e==nil{t.Fatal("nan accepted")}}
func TestLearnedHoldout(t *testing.T){a,b:=rigs();train,e:=Dataset(a,b,16,40);if e!=nil{t.Fatal(e)};all,e:=Dataset(a,b,21,40);if e!=nil{t.Fatal(e)};test:=all[len(train):];l,e:=Train(train,1);if e!=nil{t.Fatal(e)};q,e:=Train(train,2);if e!=nil{t.Fatal(e)};copyM,e:=Evaluate(test,b,func(p Pose)(Pose,error){return p,nil});if e!=nil{t.Fatal(e)};linM,e:=Evaluate(test,b,l.Predict);if e!=nil{t.Fatal(e)};quadM,e:=Evaluate(test,b,q.Predict);if e!=nil{t.Fatal(e)};t.Logf("heldout=%d direct=%.8f m linear=%.8f m polynomial=%.8f m",len(test),copyM.MeanFootErrorM,linM.MeanFootErrorM,quadM.MeanFootErrorM);if !(linM.MeanFootErrorM<copyM.MeanFootErrorM&&quadM.MeanFootErrorM<copyM.MeanFootErrorM){t.Fatal("no learned improvement on this narrow holdout")}}
func TestCriticNeverOverridesGeometry(t *testing.T){f:=Finding{Status:"OBSERVED",Kind:"looks_correct",ModelID:"simulated-only",StartFrame:0,EndFrame:10,Confidence:1};if z:=Adjudicate(Metrics{Count:10,MaxFootErrorM:.1},.005,f);z!="HARD_GEOMETRY_FAIL"{t.Fatal(z)};if z:=Adjudicate(Metrics{Count:10},.005,Finding{Status:"OBSERVED",Kind:"looks_correct",ModelID:"model",Confidence:math.NaN()});z!="CRITIC_UNVERIFIED"{t.Fatal(z)};if z:=Adjudicate(Metrics{Count:10},.005,f);z!="NUMERIC_PASS_VISUAL_UNQUALIFIED"{t.Fatal(z)}}
